/* Regression assertions for bounded amendments. Passing is not clinical approval. */
'use strict';
const fs=require('fs'),vm=require('vm'),assert=require('node:assert/strict');
const json=p=>JSON.parse(fs.readFileSync(p,'utf8'));
let checks=0;function check(label,value){assert.ok(value,label);checks++;}
const meds=json('data/medications.json'),rows=json('data/dilutionSource.json').records;
const med=n=>meds.find(x=>x.n===n),r=n=>rows.find(x=>x.row===n);
check('923 preserved',meds.length===923&&new Set(meds.map(x=>x.n)).size===923);
check('No blanket validation',meds.every(x=>x.validationStatus.startsWith('Revisão integral pendente')));
for(const n of ['Alopurinol','Leflunomida','Metildopa','Isotretinoína oral','Febuxostate'])check(n+' targeted provenance',!!med(n).auditCorrections);
check('Leflunomide moderate renal contraindication',med('Leflunomida').renal.includes('moderada a grave é uma contraindicação'));
check('Allopurinol dose and tests',med('Alopurinol').hepatic.includes('doses reduzidas')&&med('Alopurinol').hepatic.includes('testes periódicos'));
check('Methyldopa timeline',med('Metildopa').hepatic.includes('6–12 semanas'));
check('Isotretinoin hepatic restriction',med('Isotretinoína oral').hepatic.includes('contraindicação'));
check('Tiamazol no borrowed carbimazole link',!JSON.stringify([med('Tiamazol').src,med('Tiamazol').sourceRegulatory]).includes('/13015/'));
check('Remifentanil units corrected',r(483).administration.includes('20–250 microgramas/mL')&&!r(483).administration.includes('250 mg/'));
for(const id of [482,483])check('Remifentanil '+id+' manufacturer scope',r(id).reconstitution_volume.includes('Não transferir')||r(id).reconstitution_volume.includes('não transferir'));
check('No invented sufentanil recipe',r(504).dilution_volume.startsWith('Exemplo retirado'));
check('Propofol 2% differentiated',r(473).administration.includes('20 mg/mL (2%)'));
check('Intracardiac operative instruction removed',!r(21).administration.includes('punção intercostal')&&r(21).diluent===null);
check('Rocuronium rate not bolus',r(83).route.includes('não bólus'));
check('Norepinephrine incomplete recipe withheld',r(433).administration.includes('suspensas'));
check('Calcium invalid equality withdrawn',r(141).administration.includes('retirada'));
check('Insulin temperature not guessed',r(331).observations.includes('não foi convertido'));
for(const id of [332,333,334])check('Insulin mixing '+id,r(id).observations.includes('Não assumir'));
check('Lispro different scopes',r(338).stability_diluted.includes('componentes diferentes'));
check('Pantoprazole reconstitution stages',r(447).reconstitution_solvent.includes('glucose 5% só é opção de diluição posterior'));
const inst=json('data/institutional.json');
const kp=inst.stability.records.find(x=>x.code==='100004597'&&x.brand.includes('Keppra'));
check('Keppra oral 7mo with EMA',kp.stability.startsWith('7 meses')&&kp.auditSource.includes('ema.europa.eu'));
check('Vancomycin ambiguity withheld',inst.antibiotics.records.find(x=>x.id==='inf2213-065').dilution.includes('não combinar livremente'));
const fake={window:{},document:{getElementById:()=>null,querySelectorAll:()=>[],readyState:'complete',addEventListener:()=>{}},setTimeout:()=>0,setInterval:()=>0,clearInterval:()=>{},console,MutationObserver:class{observe(){}},requestAnimationFrame:()=>{}};
function evaluate(path,extension=''){
 const context=vm.createContext({...fake,window:{}});let text=fs.readFileSync(path,'utf8');
 if(extension)text=text.replace(/\}\)\(\);\s*$/,extension+'\n})();');
 vm.runInContext(text,context,{timeout:2000});return context;
}
const compat=evaluate('iv-compatibility-expanded-v3.js').window.FCCIVExpandedAudit;
const lp=compat.get('Levetiracetam','Piperacilina/tazobactam');
check('LEV/PIP three-state',lp.status==='conditional'&&lp.conditions.includes('33,75')&&lp.conditions.includes('incompatibilidade física com 45'));
check('LEV/NOR unresolved units withheld',compat.get('Levetiracetam','Noradrenalina').title.includes('suspenso'));
for(const n of ['Clindamicina','Fentanilo','Hidrocortisona','Midazolam','Morfina'])check('Paracetamol '+n+' physical only',compat.get('Paracetamol',n).note.includes('não foi avaliada quimicamente'));
check('Expanded positives conditional',Object.values(['Cisatracúrio','Dexmedetomidina','Propofol','Vancomicina','Vasopressina']).every(n=>compat.get('Levetiracetam',n).status==='conditional'));
const st=evaluate('dilutions-document-db-v4.js','window.testStandard=currentStandard;').window.testStandard;
check('No combination inherits monotherapy',st('Lidocaína 20mg/ml + Adrenalina 0.01mg/ml','Perfusão IV')===null);
check('No IV infusion standard on IM',st('Adrenalina 1mg/ml','IM')===null);
check('No infusion standard on direct IV',st('Adrenalina 1mg/ml','IV')===null);
check('Propofol 20 not 10 reference',st('Propofol 20mg/ml Emul','Perfusão IV').value.startsWith('20 mg/mL'));
check('Valid reference still selectable',st('Noradrenalina 1 mg/ml','Perfusão IV')!==null);
const ctx=evaluate('medication-stability-cuf-v1.js','window.testMatch=matches;window.setRecords=(x)=>records=x;');
ctx.window.setRecords(inst.stability.records);
const excluded=['Amoxicilina/ácido clavulânico oral','Budesonida/formoterol','Tramadol/paracetamol','Loratadina','Fenilefrina','Azitromicina IV','Paracetamol IV'];
const expectedCounts=[2,0,0,1,4,0,0];
for(let i=0;i<excluded.length;i++)check('Wrong links removed without removing correct products '+excluded[i],ctx.window.testMatch(excluded[i]).length===expectedCounts[i]);
check('Keppra match preserved',ctx.window.testMatch('Levetiracetam').some(x=>x.code==='100004597'));
const links=meds.reduce((sum,x)=>sum+ctx.window.testMatch(x.n).length,0);
check('117 documentary associations remain',links===117);
check('No two/three-link certification',!fs.readFileSync('iv-compatibility.js','utf8').includes('Triangulação 3 fontes')&&!fs.readFileSync('iv-compatibility.js','utf8').includes('Validado em 2 fontes'));
check('No per-source state inferred',fs.readFileSync('iv-source-evidence.js','utf8').includes("const s='unknown'"));
check('Missing selector names restored',fs.readFileSync('iv-catalogue.js','utf8').includes("['Verapamil','Vecurónio']"));
const log=json('data/medication-corrections-20260923.json');
check('47 tracked field amendments',log.changes.length===47);
check('Ledger traceability',log.changes.every(x=>x.findings&&'before'in x&&'after'in x));
console.log(JSON.stringify({result:'PASS',checks,stabilityAssociations:links,fieldAmendments:log.changes.length,scope:'Software/data assertions, not full clinical verification'}));
